//! The frozen eid-circuits circuits and the document proof.
//!
//! [`circuits`] is generated by `noir-zk-codegen` from `circuits/manifest.toml`
//! and `resources/` (written by `noir-zk freeze`, see `mise run freeze`): per
//! active circuit, typed inputs and a marker implementing `Circuit` and
//! `CircuitId` (with its Chonk verification key embedded), plus
//! [`circuits::REGISTRY`] over every version and the key tree root.
//!
//! Bytecode isn't embedded (about 730 MB for all circuits): [`artifacts`]
//! fetches it from a store and rejects it unless it hashes to the pinned
//! value. Verification needs no bytecode: [`hiding_vk`] and [`vk_tree_root`]
//! are all a verifier pins.

pub mod fold;

use noir_zk_backend::{ArtifactStore, Frozen};
use noir_zk_core::codec::field_from_be_bytes_canonical;
use noir_zk_core::registry::active;
use noir_zk_core::{Error, Field};

pub use fold::{prove_document, verify_document, Document, Inputs, PublicOutputs};
#[cfg(feature = "http")]
pub use noir_zk_backend::HttpStore;
pub use noir_zk_backend::{chonk::FoldedProof, DirStore};

/// Generated from the frozen registry (see the crate docs).
#[allow(missing_docs, clippy::all)]
pub mod circuits {
    include!(concat!(env!("OUT_DIR"), "/circuits.rs"));
}

/// The frozen circuits with bytecode from `store`, for [`prove_document`].
pub fn artifacts<S: ArtifactStore>(store: S) -> Result<Frozen<S>, Error> {
    Frozen::new(circuits::REGISTRY, &circuits::VK_TREE_ROOT, store)
}

/// The hiding kernel's verification key: every document proof verifies under it.
pub fn hiding_vk() -> &'static [u8] {
    active(circuits::REGISTRY, "kernel_hiding").map_or(&[], |e| e.vk)
}

/// The verification key tree root a document proof must carry.
pub fn vk_tree_root() -> Field {
    field_from_be_bytes_canonical(&circuits::VK_TREE_ROOT, "vk tree root").unwrap_or_default()
}
#[cfg(test)]
mod tests {
    use super::*;
    use noir_zk_core::registry::Status;
    use noir_zk_core::{Circuit, CircuitId, CircuitKind};

    #[test]
    fn registry_is_complete() {
        let active: Vec<_> = circuits::REGISTRY
            .iter()
            .filter(|e| e.status == Status::Active)
            .collect();
        assert_eq!(active.len(), 301);
        assert_eq!(
            active
                .iter()
                .filter(|e| e.kind == CircuitKind::Kernel)
                .count(),
            4
        );
        assert_eq!(
            active
                .iter()
                .filter(|e| e.kind == CircuitKind::Hiding)
                .count(),
            1
        );
        assert!(active
            .iter()
            .all(|e| e.kind == CircuitKind::Hiding || e.vk_index.is_some()));
        assert!(!hiding_vk().is_empty());
    }

    #[test]
    fn generated_types_flatten_to_the_abi_size() {
        use circuits::kernel_tail::{Inputs, KernelTail, MerklePath, Vk};
        let w = Inputs {
            prev: [Field::from(1u64); 26],
            prev_vk: Vk {
                key: [Field::from(2u64); 151],
                path: MerklePath {
                    index: Field::from(3u64),
                    siblings: [Field::from(4u64); 9],
                },
            },
        };
        let v = KernelTail::witness_inputs(&w, &());
        assert_eq!(v.len(), 26 + 151 + 1 + 9);
        assert_eq!(
            (v[0], v[26], v[26 + 151], v[26 + 152]),
            (1u64, 2, 3, 4).into_fields()
        );
        assert_eq!(KernelTail::LABEL, "kernel_tail");
        assert_eq!(KernelTail::KIND, CircuitKind::Kernel);
        assert_eq!(
            KernelTail::VK_BYTES,
            active(circuits::REGISTRY, "kernel_tail").unwrap().vk
        );
    }

    trait IntoFields {
        fn into_fields(self) -> (Field, Field, Field, Field);
    }
    impl IntoFields for (u64, u64, u64, u64) {
        fn into_fields(self) -> (Field, Field, Field, Field) {
            (self.0.into(), self.1.into(), self.2.into(), self.3.into())
        }
    }
}
